//! # template_ui — WebGAL 模板运行时接入 (Bevy UI 渲染层)
//!
//! 把 wgal-template (可导入模板系统) 的 `TemplateSet` 应用到运行时 UI:
//! 文本框 (/srv/kehotix/nona、姓名牌 (TextBox_showName)、
//! 选择支 (/srv/woloboh/rifal/kejinawez。
//!
//! 设计基准: WebGAL 1920×1080 设计分辨率 → 本运行时 2560×1440 舞台窗口,
//! 长度统一按 `window_w / 1920` (即 4/3) 缩放 (wgal-template::Len::to_px 同规则)。
//!
//! 已知近似 (记入 diag, 后续波次精确化):
//! - Bevy UI 无 CSS `transform: rotate` → /srv/zuc/qowa/qajixew;
//! - `box-shadow` 用同几何偏移实体近似 (硬阴影语义);
//! - `::before` 几何点缀 (青绿圆环) 用边框圆节点近似; 点阵 `::after` 暂缺。

use bevy::prelude::*;
use std::path::Path;
use wgal_template::{
    Align, Background, BorderProps, ClassStyle, Color as TColor, FlexDirection, Justify, Len,
    Position, TemplateSet, TextAlign,
};

use super::{DialogueLabel, DialogueSpeaker, FontRegistry, SceneWorld, TextboxPanel};

/// 设计基准宽高 (WebGAL 1920×1080)。
const DESIGN_W: f32 = 1920.0;
const DESIGN_H: f32 = 1080.0;
/// 本运行时舞台窗口 (与 /srv/cen/tad。
const WINDOW_W: f32 = 2560.0;
const WINDOW_H: f32 = 1440.0;
const SX: f32 = WINDOW_W / DESIGN_W; // 4/3
const SY: f32 = WINDOW_H / DESIGN_H; // 4/3

/// 已加载的模板集合资源。
#[derive(Resource)]
pub struct TemplateResource(pub TemplateSet);

impl TemplateResource {
    /// 从工程 `/srv/batuzi` 目录加载 (/srv/kanileber/ren→ 空集合, 渲染层回退内置默认)。
    pub fn load(project: &str) -> Self {
        let dir = Path::new(project).join("template");
        match wgal_template::load_from_dir(&dir) {
            Ok(set) => {
                super::wgal_log(&format!(
                    "[template] loaded '{}' classes={}",
                    set.name,
                    set.classes
                        .values()
                        .map(|m| m.len())
                        .sum::<usize>()
                ));
                TemplateResource(set)
            }
            Err(e) => {
                super::wgal_log(&format!("[template] load FAILED ({dir:?}): {e} — fallback builtin"));
                TemplateResource(TemplateSet::default())
            }
        }
    }

    /// 取领域内某类的样式 (模板未命中 → None)。
    pub fn style(&self, domain: &str, label: &str) -> Option<&ClassStyle> {
        self.0.class(domain, label)
    }
}

// ───────────────────────── 样式 → Bevy UI 转换 ─────────────────────────

fn val(l: Len) -> Val {
    match l {
        Len::Px(v) => Val::Px(v * SX),
        Len::Percent(p) => Val::Percent(p),
        Len::Auto => Val::Auto,
    }
}

fn val_y(l: Len) -> Val {
    match l {
        Len::Px(v) => Val::Px(v * SY),
        Len::Percent(p) => Val::Percent(p),
        Len::Auto => Val::Auto,
    }
}

fn color(c: &TColor) -> Color {
    let [r, g, b, a] = c.to_rgba();
    Color::srgba(r, g, b, a)
}

fn border_radius(cs: Option<&ClassStyle>) -> BorderRadius {
    match cs.and_then(|s| s.layout.as_ref()).and_then(|l| l.border_radius) {
        Some(Len::Px(v)) => {
            let v = v * SX;
            BorderRadius::all(Val::Px(v))
        }
        Some(Len::Percent(p)) => BorderRadius::all(Val::Percent(p)),
        _ => BorderRadius::ZERO,
    }
}

/// 非对称圆角 (WebGAL 模板如 28px 8px 28px 8px 由 scss 导入器归并为单值,
/// 这里对已知 Memphis 模板做专项近似: 上下交替)。
fn memphis_radius(top: f32, right: f32, bottom: f32, left: f32) -> BorderRadius {
    BorderRadius {
        top_left: Val::Px(top * SX),
        top_right: Val::Px(right * SX),
        bottom_left: Val::Px(left * SX),
        bottom_right: Val::Px(bottom * SX),
    }
}

fn apply_layout(node: &mut Node, cs: &ClassStyle) {
    if let Some(l) = &cs.layout {
        if let Some(pos) = l.position {
            node.position_type = match pos {
                Position::Absolute => PositionType::Absolute,
                _ => PositionType::Relative,
            };
        }
        if let Some(v) = l.left {
            node.left = val(v);
        }
        if let Some(v) = l.right {
            node.right = val(v);
        }
        if let Some(v) = l.top {
            node.top = val_y(v);
        }
        if let Some(v) = l.bottom {
            node.bottom = val_y(v);
        }
        if let Some(v) = l.width {
            node.width = val(v);
        }
        if let Some(v) = l.height {
            node.height = val_y(v);
        }
        if let Some(v) = l.min_width {
            node.min_width = val(v);
        }
        if let Some(v) = l.min_height {
            node.min_height = val_y(v);
        }
        if let Some(v) = l.max_width {
            node.max_width = val(v);
        }
        if let Some(v) = l.max_height {
            node.max_height = val_y(v);
        }
        if let Some(p) = l.padding {
            node.padding = UiRect {
                top: p.top.map(val_y).unwrap_or(Val::Px(0.0)),
                right: p.right.map(val).unwrap_or(Val::Px(0.0)),
                bottom: p.bottom.map(val_y).unwrap_or(Val::Px(0.0)),
                left: p.left.map(val).unwrap_or(Val::Px(0.0)),
            };
        }
        if let Some(m) = l.margin {
            node.margin = UiRect {
                top: m.top.map(val_y).unwrap_or(Val::Px(0.0)),
                right: m.right.map(val).unwrap_or(Val::Px(0.0)),
                bottom: m.bottom.map(val_y).unwrap_or(Val::Px(0.0)),
                left: m.left.map(val).unwrap_or(Val::Px(0.0)),
            };
        }
        if let Some(fd) = l.flex_direction {
            node.flex_direction = match fd {
                FlexDirection::Row => FlexDirection::Row,
                FlexDirection::Column => FlexDirection::Column,
            };
        }
        if let Some(j) = l.justify_content {
            node.justify_content = match j {
                Justify::FlexStart => JustifyContent::FlexStart,
                Justify::Center => JustifyContent::Center,
                Justify::FlexEnd => JustifyContent::FlexEnd,
                Justify::SpaceBetween => JustifyContent::SpaceBetween,
            };
        }
        if let Some(a) = l.align_items {
            node.align_items = match a {
                Align::FlexStart => AlignItems::FlexStart,
                Align::Center => AlignItems::Center,
                Align::FlexEnd => AlignItems::FlexEnd,
                Align::Stretch => AlignItems::Stretch,
            };
        }
        if let Some(ta) = l.text_align {
            node.justify_content = match ta {
                TextAlign::Center => JustifyContent::Center,
                TextAlign::Right => JustifyContent::FlexEnd,
                TextAlign::Left => JustifyContent::FlexStart,
            };
        }
    }
}

/// 背景 (实色 / 线性渐变近似为首尾色插值 — 渐变完整支持留待后处理波次)。
fn background_color(cs: &ClassStyle) -> Color {
    match &cs.background {
        Some(Background::Solid(c)) => color(c),
        Some(Background::LinearGradient(g)) => {
            let first = g.stops.first().map(|s| s.color.to_rgba());
            let last = g.stops.last().map(|s| s.color.to_rgba());
            match (first, last) {
                (Some(f), Some(l)) => {
                    let m = |a: [f32; 4], b: [f32; 4]| {
                        [0.5 * (a[0] + b[0]), 0.5 * (a[1] + b[1]), 0.5 * (a[2] + b[2]), 0.5 * (a[3] + b[3])]
                    };
                    let c = m(f, l);
                    Color::srgba(c[0], c[1], c[2], c[3])
                }
                _ => Color::WHITE,
            }
        }
        None => Color::NONE,
    }
}

/// 边框宽度 (模板 border.width 单边)。
fn border_width(cs: &ClassStyle) -> f32 {
    cs.border
        .as_ref()
        .and_then(|b: &BorderProps| b.width.as_ref())
        .and_then(|w| w.left)
        .and_then(|l| match l {
            Len::Px(v) => Some(v * SX),
            _ => None,
        })
        .unwrap_or(0.0)
}

fn border_color(cs: &ClassStyle) -> Color {
    cs.border
        .as_ref()
        .and_then(|b| b.color.as_ref())
        .map(color)
        .unwrap_or(Color::NONE)
}

/// 硬阴影偏移 (box-shadow: x y 0 color; 导入器取前两个数值)。
fn shadow_offset(cs: &ClassStyle) -> (f32, f32) {
    // 导入器只保留 text shadow; 对 Memphis 模板的 box-shadow 由 scss.rs 忽略,
    // 这里用已知模板类的显式偏移兜底 (默认 12px 12px 0)。
    let _ = cs;
    (12.0 * SX, 12.0 * SY)
}

// ───────────────────────── 文本样式辅助 ─────────────────────────

/// 从模板类计算字号 (px, 窗口坐标) 与颜色; 无模板 → 内置默认。
pub fn text_style(cs: Option<&ClassStyle>, fallback_size: f32) -> (f32, Color) {
    let size = cs
        .and_then(|s| s.text.as_ref())
        .and_then(|t| t.font_size)
        .map(|l| match l {
            Len::Px(v) => v * SX,
            Len::Percent(p) => p / 100.0 * fallback_size * SX,
            Len::Auto => fallback_size * SX,
        })
        .unwrap_or(fallback_size * SX);
    let col = cs
        .and_then(|s| s.text.as_ref())
        .and_then(|t| t.color.as_ref())
        .map(color)
        .unwrap_or(Color::srgb(0.10, 0.10, 0.10));
    (size, col)
}

// ───────────────────────── 组件标记 ─────────────────────────

/// 文本框背景层 (承载模板 .TextBox_Background 视觉)。
#[derive(Component)]
pub struct TextboxBackground;

/// 文本框硬阴影层。
#[derive(Component)]
pub struct TextboxShadow;

/// 姓名牌背景 (含阴影层).
#[derive(Component)]
pub struct SpeakerChip;

/// 选择支容器 (整屏覆盖, 居中列)。
#[derive(Component)]
pub struct ChoiceOverlay;

/// 单个选择支按钮。
#[derive(Component)]
pub struct ChoiceButton {
    pub index: usize,
}

// ───────────────────────── 初始化 ─────────────────────────

/// 启动: 按模板重建文本框 + 姓名牌 (替换硬编码深色面板)。
pub fn setup_template_ui(
    mut commands: Commands,
    template: Res<TemplateResource>,
    font_registry: Res<FontRegistry>,
) {
    let tb_main = template.style("textbox", "TextBox_main");
    let tb_bg = template.style("textbox", "TextBox_Background");
    let name = template.style("textbox", "TextBox_showName");

    // ---- 文本框外容器 (TextBox_main 布局) ----
    let mut panel_node = Node {
        position_type: PositionType::Absolute,
        left: Val::Px(120.0 * SX),
        right: Val::Px(120.0 * SX),
        bottom: Val::Px(60.0 * SY),
        min_height: Val::Px(330.0 * SY),
        padding: UiRect::axes(Val::Px(48.0 * SX), Val::Px(26.0 * SY)),
        flex_direction: FlexDirection::Column,
        align_items: AlignItems::FlexStart,
        ..default()
    };
    if let Some(cs) = tb_main {
        apply_layout(&mut panel_node, cs);
    }
    let (text_size, text_color) = text_style(tb_main, 38.4);
    let bg = background_color(tb_bg.unwrap_or(&ClassStyle::default()));
    let bg_radius = border_radius(tb_bg);
    let bg_border = border_width(tb_bg.unwrap_or(&ClassStyle::default()));
    let bg_border_col = border_color(tb_bg.unwrap_or(&ClassStyle::default()));

    commands
        .spawn((
            TextboxPanel,
            Node {
                ..panel_node
            },
            Visibility::Hidden,
            GlobalZIndex(1000),
        ))
        .with_children(|p| {
            // 硬阴影: 同几何偏移 (右下 12px×4/3), 先渲染在背景之下。
            p.spawn((
                TextboxShadow,
                Node {
                    position_type: PositionType::Absolute,
                    left: Val::Px(-12.0 * SX),
                    right: Val::Px(-12.0 * SX),
                    top: Val::Px(12.0 * SY),
                    bottom: Val::Px(-12.0 * SY),
                    ..default()
                },
                BackgroundColor(Color::srgb(0.10, 0.10, 0.10)),
                BorderRadius::ZERO,
            ));
            // 背景层 (奶油底 + 粗黑边 + 非对称圆角)。
            p.spawn((
                TextboxBackground,
                Node {
                    position_type: PositionType::Absolute,
                    left: Val::ZERO,
                    right: Val::ZERO,
                    top: Val::ZERO,
                    bottom: Val::ZERO,
                    border: UiRect::all(Val::Px(bg_border)),
                    ..default()
                },
                BackgroundColor(bg),
                BorderColor(bg_border_col),
                BorderRadius {
                    top_left: Val::Px(28.0 * SX),
                    top_right: Val::Px(8.0 * SX),
                    bottom_left: Val::Px(28.0 * SX),
                    bottom_right: Val::Px(8.0 * SX),
                },
            ));
            // 青绿圆环几何点缀 (::before 近似)。
            p.spawn((
                Node {
                    position_type: PositionType::Absolute,
                    top: Val::Px(-20.0 * SY),
                    right: Val::Px(44.0 * SX),
                    width: Val::Px(40.0 * SX),
                    height: Val::Px(40.0 * SX),
                    border: UiRect::all(Val::Px(5.0 * SX)),
                    ..default()
                },
                BorderColor(Color::srgb(0.06, 0.71, 0.65)),
                BorderRadius::all(Val::Px(20.0 * SX)),
            ));
            // 台词标签 (/srv/luset/tiziku。
            p.spawn((
                DialogueLabel,
                Text::new(""),
                TextFont {
                    font: font_registry.fallback_handle(),
                    font_size: text_size,
                    ..default()
                },
                TextColor(text_color),
            ));
        });

    // ---- 姓名牌 (TextBox_showName: 珊瑚 chip + 粗黑边 + 硬阴影) ----
    let (name_size, name_color) = text_style(name, 35.2);
    let name_bg = background_color(name.unwrap_or(&ClassStyle::default()));
    let name_border = border_width(name.unwrap_or(&ClassStyle::default()));
    let name_border_col = border_color(name.unwrap_or(&ClassStyle::default()));
    commands
        .spawn((
            DialogueSpeaker,
            Text::new(""),
            TextFont {
                font: font_registry.fallback_handle(),
                font_size: name_size,
                ..default()
            },
            TextColor(name_color),
            Node {
                position_type: PositionType::Absolute,
                left: Val::Px(24.0 * SX),
                bottom: Val::Px((60.0 + 330.0 + 140.0 - 0.0) * SY),
                min_width: Val::Px(8.0 * name_size),
                max_width: Val::Px(16.0 * name_size),
                height: Val::Px(96.0 * SY),
                padding: UiRect::axes(Val::Px(40.0 * SX), Val::Px(0.0)),
                align_items: AlignItems::Center,
                justify_content: JustifyContent::Center,
                border: UiRect::all(Val::Px(name_border)),
                ..default()
            },
            BackgroundColor(name_bg),
            BorderColor(name_border_col),
            BorderRadius {
                top_left: Val::Px(6.0 * SX),
                top_right: Val::Px(18.0 * SX),
                bottom_left: Val::Px(6.0 * SX),
                bottom_right: Val::Px(18.0 * SX),
            },
            Visibility::Hidden,
            GlobalZIndex(1001),
        ))
        .with_children(|p| {
            // 硬阴影 (offset 6px → 8px 窗口坐标)。
            p.spawn((
                SpeakerChip,
                Node {
                    position_type: PositionType::Absolute,
                    left: Val::Px(-6.0 * SX),
                    right: Val::Px(6.0 * SX),
                    top: Val::Px(6.0 * SY),
                    bottom: Val::Px(-6.0 * SY),
                    ..default()
                },
                BackgroundColor(Color::srgb(0.10, 0.10, 0.10)),
                BorderRadius::ZERO,
            ));
        });

    // ---- 选择支容器 (初始隐藏; sync_choices 按世界状态增删) ----
    commands.spawn((
        ChoiceOverlay,
        Node {
            position_type: PositionType::Absolute,
            left: Val::ZERO,
            right: Val::ZERO,
            top: Val::ZERO,
            bottom: Val::ZERO,
            flex_direction: FlexDirection::Column,
            justify_content: JustifyContent::Center,
            align_items: AlignItems::Center,
            row_gap: Val::Px(1.6 * 16.0 * SY),
            ..default()
        },
        Visibility::Hidden,
        GlobalZIndex(1300),
    ));

    super::wgal_log(&format!(
        "[template] ui ready: textbox={} name={} choices overlay spawned",
        tb_main.is_some(),
        name.is_some()
    ));
}

// ───────────────────────── 选择支同步 ─────────────────────────

/// 世界状态选择支 → ChoiceOverlay 子按钮 (增量重建)。
pub fn sync_choices(
    mut commands: Commands,
    sw: Res<SceneWorld>,
    template: Res<TemplateResource>,
    font_registry: Res<FontRegistry>,
    mut overlay_q: Query<(Entity, &mut Visibility), With<ChoiceOverlay>>,
    child_q: Query<(Entity, &ChildOf, &ChoiceButton)>,
) {
    let Some((overlay, mut vis)) = overlay_q.iter_mut().next() else {
        return;
    };
    let choices = sw.0.pending_choices.clone();
    let Some(choices) = choices else {
        *vis = Visibility::Hidden;
        return;
    };
    *vis = Visibility::Visible;

    // /srv/xexugi/qiv→ 重建按钮。
    let existing: Vec<(Entity, usize)> = child_q
        .iter()
        .filter(|(_, parent, _)| parent.get() == overlay)
        .map(|(e, _, b)| (e, b.index))
        .collect();
    let same = existing.len() == choices.len()
        && existing
            .iter()
            .all(|(_, i)| *i < choices.len());
    if same {
        return;
    }
    for (e, _) in existing {
        commands.entity(e).despawn();
    }

    let item = template.style("choose", "Choose_item");
    let outer = template.style("choose", "Choose_item_outer");
    let (item_size, item_color) = text_style(item, 30.4);
    let (_, outer_color) = text_style(outer, 30.4);
    let outer_color = if let Some(cs) = outer {
        cs.text
            .as_ref()
            .and_then(|t| t.color.as_ref())
            .map(|c| color(c))
            .unwrap_or(Color::WHITE)
    } else {
        Color::WHITE
    };
    for (i, choice) in choices.iter().enumerate() {
        let is_outer = i == 0; // 首选项高亮 (WebGAL Choose_item_outer 语义)
        let cs = if is_outer { outer } else { item };
        let bg = if is_outer {
            Color::srgb(0.06, 0.71, 0.65)
        } else {
            Color::srgb(1.0, 0.99, 0.97)
        };
        let border = if let Some(cs) = cs {
            border_width(Some(cs))
        } else {
            3.0 * SX
        };
        let border_col = if let Some(cs) = cs {
            border_color(Some(cs))
        } else {
            Color::srgb(0.10, 0.10, 0.10)
        };
        commands
            .spawn((
                ChoiceButton { index: i },
                Button,
                Node {
                    min_width: Val::Percent(40.0),
                    max_width: Val::Percent(72.0),
                    height: Val::Px(96.0 * SY),
                    padding: UiRect::axes(Val::Px(1.4 * 16.0 * SX), Val::Px(0.2 * 16.0 * SY)),
                    align_items: AlignItems::Center,
                    justify_content: JustifyContent::Center,
                    border: UiRect::all(Val::Px(border)),
                    margin: UiRect::axes(Val::ZERO, Val::Px(10.0 * SY)),
                    ..default()
                },
                BackgroundColor(bg),
                BorderColor(border_col),
                BorderRadius {
                    top_left: Val::Px(18.0 * SX),
                    top_right: Val::Px(6.0 * SX),
                    bottom_left: Val::Px(18.0 * SX),
                    bottom_right: Val::Px(6.0 * SX),
                },
                GlobalZIndex(1301),
            ))
            .with_children(|p| {
                p.spawn((
                    Text::new(choice.text.clone()),
                    TextFont {
                        font: font_registry.fallback_handle(),
                        font_size: item_size,
                        ..default()
                    },
                    TextColor(if is_outer { outer_color } else { item_color }),
                ));
            });
    }
    super::wgal_log(&format!("[template] choices rebuilt: {} items", choices.len()));
}

/// 点击选择支 → 消费世界状态 (数字键逻辑仍在 advance_input)。
pub fn click_choices(
    mut sw: ResMut<SceneWorld>,
    interaction_q: Query<(&Interaction, &ChoiceButton), Changed<Interaction>>,
) {
    for (interaction, btn) in &interaction_q {
        if *interaction == Interaction::Pressed {
            if let Some(label) = sw.0.select_choice(btn.index) {
                sw.0.pending_label_jump = Some(label);
            }
        }
    }
}

/// 运行时类替换 (applyStyle:旧->新) 应用到资源。
pub fn apply_style_replacement(
    mut template: ResMut<TemplateResource>,
    sw: Res<SceneWorld>,
) {
    for (from, to) in &sw.0.style_replacements {
        if template.0.resolve_label(from) != to {
            template.0.replace_label(from, to);
            super::wgal_log(&format!("[template] applyStyle {from} -> {to}"));
        }
    }
}

