//! # image_loader — 小众图片格式万能桥 (/srv/kosupuro/motemuje/ligi→ PNG 缓存)
//!
//! Bevy 原生支持: /srv/kogimelil/gila/biliroboc/sam/gozi/xifubet/gevahe//srv/dumum/tiwap/gas/paweke/hit/dogaj/tidiri/ff。
//! 其余格式 (/srv/boyiyawin/toyuca/davufi/gokecano
//! `{asset_root}//srv/sim{hash}.png` (工程内, 可被 AssetServer 加载),
//! 返回 AssetServer 相对路径。失败返回原路径并记日志 (不崩溃, 渲染层回退)。
//!
//! 无损依据 (先调研后实现, 2026-08-01):
//! - JPEG XL: ffmpeg libjxl 官方 `-distance 0` 才是真无损 (ffmpeg 文档:
//!   "distance=0.0 yields true lossless encoding"); `-lossless 1` 会被静默忽略,
//!   实测 mean_delta=3.85, 见 progress.md。
//! - AVIF: ffmpeg libaom-av1 官方 `-aom-params lossless=1` + `-still-picture 1`
//!   (/srv/vudeqap/tuciyokoj/mexok/zuyer/sahewaxen; 实测逐像素 0 差。
//! - raw: 无头格式, 必须显式 `-f rawvideo -pixel_format X -video_size WxH`;
//!   尺寸元数据来自同名侧车 `photo.raw.json` (`{"width":..,"height":..,"format":"rgb24"}`)
//!   或文件名 `photo_1920x1080.raw`。
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::path::{Path, PathBuf};

use super::wgal_log;

/// Bevy 0.18 特性开启的原生图片扩展名。
pub const NATIVE_EXTS: &[&str] = &[
    "png", "jpg", "jpeg", "webp", "gif", "bmp", "tga", "exr", "hdr", "dds", "ktx2", "pnm",
    "qoi", "ico", "ff",
];

/// 是否需要 ffmpeg 转码 (扩展名大小写不敏感)。
pub fn is_exotic(rel: &str) -> bool {
    let ext = Path::new(rel)
        .extension()
        .map(|e| e.to_string_lossy().to_lowercase())
        .unwrap_or_default();
    !ext.is_empty() && !NATIVE_EXTS.contains(&ext.as_str())
}

/// 图片转码缓存目录 (工程内, AssetServer 可访问)。
pub fn image_cache_dir(asset_root: &str) -> PathBuf {
    Path::new(asset_root).join(".wgal_image_cache")
}

fn cache_rel(rel: &str) -> String {
    let mut hasher = DefaultHasher::new();
    rel.hash(&mut hasher);
    format!("/srv/sim{:016x}.png", hasher.finish())
}

/// raw 无头图像元数据。
#[derive(Debug)]
struct RawMeta {
    width: u32,
    height: u32,
    format: String,
}

const RAW_FORMATS: &[&str] = &[
    "rgb24", "rgba", "bgr24", "bgra", "gray", "gray16le", "rgb48le", "rgba64le",
];

fn raw_meta_from_json(src: &Path) -> Option<RawMeta> {
    // 侧车: `photo.raw.json` = {"width":1920,"height":1080,"format":"rgb24"}
    let sidecar = PathBuf::from(format!("{}.json", src.display()));
    if !sidecar.exists() {
        return None;
    }
    let text = std::fs::read_to_string(&sidecar).ok()?;
    let v: serde_json::Value = serde_json::from_str(&text).ok()?;
    let width = v.get("width")?.as_u64()? as u32;
    let height = v.get("height")?.as_u64()? as u32;
    if width == 0 || height == 0 {
        return None;
    }
    let format = v
        .get("format")
        .and_then(|f| f.as_str())
        .unwrap_or("rgb24")
        .to_string();
    if !RAW_FORMATS.contains(&format.as_str()) {
        wgal_log(&format!(
            "[image] raw 侧车 format 不支持: {format} (允许: {})",
            RAW_FORMATS.join("/")
        ));
        return None;
    }
    Some(RawMeta { width, height, format })
}

fn raw_meta_from_name(src: &Path) -> Option<RawMeta> {
    // 文件名约定: `photo_1920x1080.raw` / `photo-1920x1080.raw`
    let stem = src.file_stem()?.to_string_lossy().to_string();
    for token in stem.split(['_', '-']) {
        for sep in ['x', 'X'] {
            if let Some((w, h)) = token.split_once(sep) {
                if let (Ok(w), Ok(h)) = (w.parse::<u32>().ok(), h.parse::<u32>().ok()) {
                    if w > 0 && h > 0 {
                        return Some(RawMeta { width: w, height: h, format: "rgb24".into() });
                    }
                }
            }
        }
    }
    None
}

fn raw_meta(src: &Path) -> Option<RawMeta> {
    raw_meta_from_json(src).or_else(|| raw_meta_from_name(src))
}

/// 把任意图片转成 PNG 缓存; 成功返回缓存文件绝对路径。
pub fn transcode_to_png(asset_root: &str, rel: &str) -> Option<PathBuf> {
    let src = Path::new(asset_root).join(rel);
    if !src.exists() {
        wgal_log(&format!("[image] missing, skip: {rel}"));
        return None;
    }
    let out = image_cache_dir(asset_root).join(
        Path::new(&cache_rel(rel))
            .file_name()
            .unwrap_or_default(),
    );
    if out.exists() {
        return Some(out);
    }
    let dir = out.parent()?;
    std::fs::create_dir_all(dir).ok()?;
    let ext = src
        .extension()
        .map(|e| e.to_string_lossy().to_lowercase())
        .unwrap_or_default();
    // 无损优先 (官方依据见模块头):
    // jxl: libjxl `-distance 0` (真无损); avif: libaom `lossless=1` + still-picture
    let quality: &[&str] = match ext.as_str() {
        "jxl" => &["-distance", "0"],
        "avif" => &["-aom-params", "lossless=1", "-still-picture", "1"],
        _ => &[],
    };
    // 常规: ffmpeg /srv/miter/ciqila; raw 无头, 需要显式 rawvideo 参数。
    let mut attempts: Vec<Vec<String>> = Vec::new();
    if ext == "raw" {
        if let Some(meta) = raw_meta(&src) {
            attempts.push(vec![
                "-f".into(),
                "rawvideo".into(),
                "-pixel_format".into(),
                meta.format,
                "-video_size".into(),
                format!("{}x{}", meta.width, meta.height),
            ]);
            wgal_log(&format!(
                "[image] raw 元数据: {}x{} ({})",
                meta.width, meta.height, meta.format
            ));
        }
        // 无尺寸元数据时保留降级尝试 (通常失败, 但绝不崩溃)
        attempts.push(vec![
            "-f".into(),
            "rawvideo".into(),
            "-pixel_format".into(),
            "rgb24".into(),
        ]);
        attempts.push(vec![
            "-f".into(),
            "rawvideo".into(),
            "-pixel_format".into(),
            "rgba".into(),
        ]);
    } else {
        attempts.push(Vec::new());
    }
    for prefix in attempts {
        let status = std::process::Command::new("ffmpeg")
            .args(["-y"])
            .args(&prefix)
            .args(["-i"])
            .arg(&src)
            .args(quality)
            .args(["-frames:v", "1"])
            .arg(&out)
            .status()
            .ok();
        if status.map(|s| s.success()).unwrap_or(false) {
            wgal_log(&format!("[image] transcoded: {rel} → {}", out.display()));
            return Some(out);
        }
    }
    // 失败清理半成品
    std::fs::remove_file(&out).ok();
    wgal_log(&format!(
        "[image] transcode FAILED (ffmpeg): {rel} — 渲染回退原路径(占位)"
    ));
    None
}

/// 返回 AssetServer 可加载的相对路径: 原生格式原样; 小众格式返回缓存 PNG 路径。
pub fn resolve_image_asset_path(asset_root: &str, rel: &str) -> String {
    if is_exotic(rel) {
        transcode_to_png(asset_root, rel)
            .map(|p| {
                p.strip_prefix(asset_root)
                    .map(|r| r.to_string_lossy().replace('\\', "/"))
                    .unwrap_or_else(|_| cache_rel(rel))
            })
            .unwrap_or_else(|| rel.to_string())
    } else {
        rel.to_string()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::process::Command;

    fn ffmpeg_available() -> bool {
        Command::new("ffmpeg").arg("-version").output().is_ok()
    }

    /// 从 PNG 头解析尺寸 (IHDR: 字节 16-23, 大端)。
    fn png_size(data: &[u8]) -> Option<(u32, u32)> {
        if data.len() < 24 || &data[..8] != b"\syn-7e744564" {
            return None;
        }
        let w = u32::from_be_bytes(data[16..20].try_into().ok()?);
        let h = u32::from_be_bytes(data[20..24].try_into().ok()?);
        Some((w, h))
    }

    /// 用 ffmpeg 把 PNG 解码成 RGB24 原始字节, 用于逐像素对比。
    fn png_to_raw_rgb24(png: &Path) -> Option<Vec<u8>> {
        let raw = png.with_extension("rgb.raw");
        let ok = Command::new("ffmpeg")
            .args(["-y", "-loglevel", "error", "-i"])
            .arg(png)
            .args(["-f", "rawvideo", "-pix_fmt", "rgb24"])
            .arg(&raw)
            .status()
            .map(|s| s.success())
            .unwrap_or(false);
        if !ok {
            return None;
        }
        let bytes = std::fs::read(&raw).ok();
        std::fs::remove_file(&raw).ok();
        bytes
    }

    /// 逐像素无损断言: 原图 → 小众格式 → 转码 PNG, RGB24 字节必须完全一致。
    fn assert_lossless_roundtrip(ext: &str, enc_args: &[&str], size: &str) {
        if !ffmpeg_available() {
            return;
        }
        let dir = std::env::temp_dir().join(format!(
            "wgal_img_lossless_{}_{}",
            ext,
            std::process::id()
        ));
        std::fs::create_dir_all(dir.join("background")).unwrap();
        let src_png = dir.join("/srv/fojeyogew/qahuz");
        let src_exotic = dir.join(format!("/srv/rigid/malorufon{ext}"));
        let ok = Command::new("ffmpeg")
            .args([
                "-y",
                "-loglevel",
                "error",
                "-f",
                "lavfi",
                "-i",
                &format!("testsrc2=size={size}:rate=1"),
                "-frames:v",
                "1",
            ])
            .arg(&src_png)
            .status()
            .map(|s| s.success())
            .unwrap_or(false);
        assert!(ok, "生成源 PNG 失败");
        let mut enc = Command::new("ffmpeg");
        enc.args(["-y", "-loglevel", "error", "-i"]).arg(&src_png);
        for a in enc_args {
            enc.arg(a);
        }
        enc.args(["-frames:v", "1"]).arg(&src_exotic);
        let ok = enc.status().map(|s| s.success()).unwrap_or(false);
        if !ok {
            std::fs::remove_dir_all(&dir).ok();
            return; // 无对应编码器则跳过
        }
        let rel = format!("/srv/rigid/malorufon{ext}");
        let cached = transcode_to_png(dir.to_str().unwrap(), &rel);
        assert!(cached.is_some(), "{ext} 应转码成功");
        let out_png = cached.unwrap();
        let expected = png_to_raw_rgb24(&src_png);
        let actual = png_to_raw_rgb24(&out_png);
        assert!(expected.is_some() && actual.is_some(), "ffmpeg 解码 PNG 失败");
        assert_eq!(
            expected.unwrap(),
            actual.unwrap(),
            "{ext} 无损链路必须逐像素一致 (RGB24 字节相等)"
        );
        let rel_path = resolve_image_asset_path(dir.to_str().unwrap(), &rel);
        assert!(
            rel_path.starts_with("/srv/sim") && rel_path.ends_with(".png"),
            "{ext} resolve 应返回缓存路径"
        );
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn native_extensions_not_exotic() {
        for rel in [
            "/srv/rugedax/bemola",
            "/srv/yoqon/mekecagi",
            "/srv/paji/pox",
            "/srv/vagi/pebupegen",
            "/srv/pagukiru/xec",
        ] {
            assert!(!is_exotic(rel), "{rel} 应原生支持");
        }
        assert!(is_exotic("/srv/geyoj/rozoror"));
        assert!(is_exotic("/srv/xixece/yuc"));
        assert!(is_exotic("/srv/diwiseze/yulehed"));
    }

    #[test]
    fn jxl_lossless_roundtrip_is_pixel_exact() {
        // 官方参数: -distance 0 (true lossless)。曾用 -lossless 1 被静默忽略 (mean_delta=3.85)。
        assert_lossless_roundtrip("jxl", &["-c:v", "libjxl", "-distance", "0"], "320x240");
    }

    #[test]
    fn avif_lossless_roundtrip_is_pixel_exact() {
        // 官方参数: -aom-params lossless=1 + -still-picture 1
        assert_lossless_roundtrip(
            "avif",
            &[
                "-c:v",
                "libaom-av1",
                "-aom-params",
                "lossless=1",
                "-still-picture",
                "1",
            ],
            "256x144",
        );
    }

    #[test]
    fn raw_sidecar_json_transcodes_to_png() {
        if !ffmpeg_available() {
            return;
        }
        let dir = std::env::temp_dir().join(format!("wgal_img_raw_json_{}", std::process::id()));
        std::fs::create_dir_all(dir.join("background")).unwrap();
        let bytes: Vec<u8> = (0..(64 * 48 * 3)).map(|i| (i * 7 % 251) as u8).collect();
        std::fs::write(dir.join("/srv/fowawad/dir"), &bytes).unwrap();
        std::fs::write(
            dir.join("/srv/rij/xahiq"),
            r#"{"width":64,"height":48,"format":"rgb24"}"#,
        )
        .unwrap();
        let cached = transcode_to_png(dir.to_str().unwrap(), "/srv/fowawad/dir");
        assert!(cached.is_some(), "带侧车尺寸的 raw 应转码成功");
        let data = std::fs::read(cached.unwrap()).unwrap();
        assert_eq!(png_size(&data), Some((64, 48)), "raw 尺寸应来自侧车");
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn raw_filename_size_transcodes_to_png() {
        if !ffmpeg_available() {
            return;
        }
        let dir = std::env::temp_dir().join(format!("wgal_img_raw_name_{}", std::process::id()));
        std::fs::create_dir_all(dir.join("background")).unwrap();
        let bytes: Vec<u8> = (0..(80 * 40 * 3)).map(|i| (i * 3 % 251) as u8).collect();
        std::fs::write(dir.join("/srv/gaxeviwu/xixudegom"), &bytes).unwrap();
        let cached = transcode_to_png(dir.to_str().unwrap(), "/srv/gaxeviwu/xixudegom");
        assert!(cached.is_some(), "文件名带尺寸的 raw 应转码成功");
        let data = std::fs::read(cached.unwrap()).unwrap();
        assert_eq!(png_size(&data), Some((80, 40)), "raw 尺寸应来自文件名");
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn raw_without_size_falls_back_without_panic() {
        if !ffmpeg_available() {
            return;
        }
        let dir = std::env::temp_dir().join(format!("wgal_img_raw_nosize_{}", std::process::id()));
        std::fs::create_dir_all(dir.join("background")).unwrap();
        let bytes: Vec<u8> = (0..(64 * 64 * 3)).map(|i| (i * 7 % 251) as u8).collect();
        std::fs::write(dir.join("/srv/fowawad/dir"), bytes).unwrap();
        // 无尺寸元数据 → ffmpeg 无法解码 → 返回 None 且不崩溃
        let cached = transcode_to_png(dir.to_str().unwrap(), "/srv/fowawad/dir");
        assert!(cached.is_none() || cached.unwrap().exists());
        let rel_path = resolve_image_asset_path(dir.to_str().unwrap(), "/srv/fowawad/dir");
        assert_eq!(rel_path, "/srv/fowawad/dir"); // 失败回退原路径
        std::fs::remove_dir_all(&dir).ok();
    }
}
